INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT 'bef7f0ce-d970-5201-90b7-f7b1584fa0a0'::uuid, '236929a5-c5ec-535c-b62b-8a3063d752e8'::uuid, 'Résidence Rio Beach', 'Résidence Rio Beach Bienvenue à Rio Beach, où le luxe rencontre la mer au cœur de Sidi Rahal. Une résidence unique alliant design moderne, confort et ambiance côtière exceptionnelle. Points forts: - Résidence fermée et sécurisée, véritable havre de paix - Livraison immédiate avec titres fonciers disponibles - Appartements spacieux: 100-140 m² - Configurations flexibles: 3 chambres ou 2 chambres + salon + cuisine + salles de bain + buanderie + balcons - Finitions haut de gamme - Parking privatif en sous-sol - Piscines et espaces verts luxuriants - Pied dans l''eau avec vues mer époustouflantes Idéal pour une résidence principale, maison de vacances ou investissement sûr. Vivez chaque jour comme une escapade en bord de mer. Prix à partir de 9 900 DH/m², selon emplacement.', 'Sidi Rahal', 'Centre Ville', 'Sidi Rahal Chatai, Centre Ville, 26175 Sidi Rahal', '26175', 'MA', NULL, NULL, 'immobilier', 'residentiel', 'residentiel', 'pret_a_livrer', 'en_commercialisation', 90, NULL, NULL, 'https://media.chridari.ma/77e3a4d4-05c5-48f2-9be5-3fd7ebbb14e3/images/01K5V708QHB7RJSD8Z7PDP63PN-medium.jpg', $j$["https://media.chridari.ma/77e3a4d4-05c5-48f2-9be5-3fd7ebbb14e3/images/01K5V708QHB7RJSD8Z7PDP63PN-medium.jpg", "https://media.chridari.ma/500436d4-857c-4e03-9e5d-f7a19e7e470f/images/01K5V7086NP20KNMFDFN285VWG-medium.jpg", "https://media.chridari.ma/a81a749f-6f6b-4139-a621-c7788ab40e4b/images/01K5V707PAH4ND526ERDNAGZR6-medium.jpg", "https://media.chr