INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT 'b21f4bee-3e23-5068-9d3d-4c8dc7fce4f6'::uuid, 'f164b894-bf5e-54b0-8a4a-b4c10eb6b3dc'::uuid, 'Adrar Business Center', 'ADRAR BUSINESS CENTER incarne une nouvelle génération de centres d''affaires, conçus comme de véritables accélérateurs de succès pour les professionnels ambitieux. Commercialisation par Signature Immobilier. ### Emplacement stratégique Idéalement situé à l''angle de l''Avenue Hassan II et de la Rue Khalid Ibn Al Walid, au cœur de Guéliz, Marrakech, il offre une visibilité exceptionnelle et un accès immédiat aux principales infrastructures, banques, administrations, hôtels, commerces et réseaux de transport. ### Un écosystème professionnel complet Plus qu''un simple espace de bureaux, ADRAR BUSINESS CENTER propose un environnement dynamique alliant performance, prestige et confort. Ses étages de bureaux flexibles peuvent être personnalisés pour s''adapter à toutes les entreprises — des startups en croissance aux sociétés établies. ### Un cadre qui élève vos ambitions Avec une architecture moderne, des finitions haut de gamme et un emplacement privilégié, ce projet se positionne comme un véritable moteur de croissance et de productivité dans le paysage économique de Marrakech. Libérez votre potentiel dans un espace professionnel conçu pour stimuler votre succès, aujourd''hui et demain.', 'Marrakech', 'Guéliz', 'Angle Avenue Hassan II et Rue Khalid Ben Walid, Guéliz, 40000 Marrakech', '40000', 'MA', NULL, NULL, 'immobilier', 'commercial_bureaux', 'commercial_bureaux', 'en_construction', 'en_commercialisation', 55, '2026-12', NULL, 'https