EQ00C3P9JK90EBV780KRMB-medium.jpg", "https://media.chridari.ma/91ad0d25-3f71-4760-b7c5-f2e8d4fce857/images/01JYEQ00MFQHMGA9V15HW5ZM3N-medium.jpg", "https://media.chridari.ma/3a76da98-c8fa-4ebf-8f07-7d9c8bf2c822/images/01JYEQ00XGWA5NMGCVK46D7TSZ-medium.jpg", "https://media.chridari.ma/286454c1-9773-4b61-b94c-c979f706ebe0/images/01JYEQ017N52KY43Q0NP7DV5FV-medium.jpg"]$j$::jsonb, 'Appartement', 'Ascenseur ,  Climatisation ,  Parking', 'Centre commercial ,  École ,  Mosquée', false, 1235000.0, 1235000.0, 1235000.0, 'MAD', '95 – 130 m2', 'b56cac00-7615-54b2-b412-f72e4ea13e7c', 'Souss Valley', 'https://chridari.ma/fr/promoters/souss-valley-kxh2k', $j$[]$j$::jsonb, $j${"source_project_id": "775b0d8c-4af0-596c-af41-d61535fcddac", "chridari_ref": "vcz2xs", "projet_id_legacy": "CHR-PRJ-vcz2xs", "reference_annonce": "AG142001", "url_source": "https://chridari.ma/fr/projects/souss-valley-appartement-agadir-vcz2xs", "chambres_min": "2", "chambres_max": "3", "seed_batch": "promoteurs_full_sifarah"}$j$::jsonb WHERE NOT EXISTS (SELECT 1 FROM public.projects x WHERE x.id = '775b0d8c-4af0-596c-af41-d61535fcddac'::uuid OR x.attributes->>'source_project_id' = '775b0d8c-4af0-596c-af41-d61535fcddac');
INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT 'a15e9026-5f63-5115-b044-ed129620d24a'::uuid, 'f0aac9d3-fb72-573d-b1d5-1c7f2b133c3f'::uuid, 'Résidence Royale', 'Résidence Royale - Un cadre de vie urbain d''exception ### Un emplacement stratégique au cœur de Kénitra La Résidence Royale bénéficie d''un emplacement privilégié sur l''avenue Hassan II, l''un des axes les plus emblématiques de la ville de Kénitra. Ce quartier dynamique offre un parfait équilibre entre vie urbaine active et environnement résidentiel serein. ### Un environnement agréable et bien structuré Le projet s''inscrit dans un cadre harmonieux, entouré d''infrastructures modernes et d''espaces organisés, favorisant une qualité de vie confortable au quotidien. L''ambiance du quartier est idéale pour les familles comme pour les actifs à la recherche de tranquillité sans s''éloigner du centre-ville. ### Un projet pensé pour le confort et la sérénité La Résidence Royale a été conçue pour offrir un environnement rassurant, fonctionnel et agréable, où chaque détail contribue à un mode de vie équilibré. Elle représente un choix judicieux pour habiter ou investir dans un secteur en pleine valorisation.', 'Kénitra', 'Maamora', '38, Avenue Hassan II, Maamora, 14000 Kénitra', '14000', 'MA', NULL, NULL, 'immobilier', 'residentiel', 'residentiel', 'pret_a_livrer', 'en_commercialisation', 90, NULL, NULL, 'https://media.chridari.ma/e8010bdf-d2b6-41ac-a795-1bccfceee0a7/images/01KFDW68NC271BY311EPT5XX93-medium.jpg', $j$["https://media.chridari.ma/e8010bdf-d2b6-41ac-a795-1bccfceee0a7/images/01KFDW68NC271BY311EPT5XX93-medium.jpg", "https://media.chri