INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT '773d9213-84f5-5b36-90ad-10c982f236fd'::uuid, 'dc4a71f2-c4ed-596c-b255-785ef41de066'::uuid, 'Résidence Tasnime', '### Résidence Tasnime – Marrakech Découvrez la Résidence Tasnime, un projet résidentiel moderne idéalement situé à Izdihar, à l''angle du boulevard Acharaf et de la route de Safi à Marrakech. Son emplacement offre un accès pratique aux commerces, services et principaux axes de la ville. La résidence propose une sélection de studios, appartements et duplex, ainsi que des locaux commerciaux, avec différentes surfaces et configurations adaptées à la résidence principale comme à l''investissement. Pensée pour offrir un cadre de vie confortable et agréable, la résidence bénéficie de prestations telles qu''une piscine, un parking, un ascenseur, un système de sécurité et des espaces extérieurs. Certains logements disposent également de terrasses ou de jardins privatifs. Avec ses différentes typologies, ses prestations et son emplacement stratégique, la Résidence Tasnime représente une opportunité intéressante pour vivre à Marrakech ou réaliser un investissement immobilier dans un secteur en développement.', 'Marrakech', 'Izdihar', 'Angle boulevard Acharaf et route de Safi, Izdihar, 40000 Marrakech', '40000', 'MA', NULL, NULL, 'immobilier', 'mixte', 'mixte', 'en_construction', 'en_commercialisation', 55, '2028-06', NULL, 'https://media.chridari.ma/13a1248a-4806-4cdc-8124-737949961407/images/01M4DK1JQ8S9A8ZJA56NX0JJ94-medium.jpg', $j$["https://media.chridari.ma/13a1248a-4806-4cdc-8124-737949961407/images/01M4DK1JQ8S9A8ZJA56NX0JJ94-medium.jpg", "ht