INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT '0c370b57-2d61-528e-917f-8edc77abd03d'::uuid, 'dc4a71f2-c4ed-596c-b255-785ef41de066'::uuid, 'Tasnime Business Center', 'Business Center Tasnime - Marrakech Situé à l''angle stratégique du boulevard Acharaf et de la route de Safi, Business Center Tasnime propose un concept d''espaces de travail moderne et raffiné, conçu pour les professionnels d''aujourd''hui et les entreprises en pleine croissance à Marrakech. ### Design Contemporain Inspirant Ce centre d''affaires livré se distingue par une architecture contemporaine élégante, des lignes épurées et une atmosphère professionnelle soignée. Chaque espace est pensé pour optimiser: - La lumière naturelle - L''efficacité opérationnelle - Le confort au quotidien Le résultat est un environnement inspirant, idéal pour les entrepreneurs, startups, équipes corporate et toute structure recherchant un cadre professionnel premium. ### Un Quartier Dynamique et Facile d''Accès Installé dans le quartier dynamique de l''Izdihar, le centre bénéficie d''une accessibilité remarquable et d''une excellente connexion urbaine. Les professionnels profitent d''une proximité immédiate avec : - Cafés et restaurants - Commerces et services du quotidien - Cliniques et structures médicales - Écoles - Salles de sport et espaces bien-être Tout ce qu''il faut pour une journée de travail fluide, efficace et parfaitement connectée est à quelques pas seulement. ### Prêt à Accueillir, Prêt à Évoluer Avec une livraison immédiate, une excellente visibilité et un emplacement au cœur de l''un des pôles les plus actifs de Marrakech, Business Center Tasnime s''impose comme une adresse professionnelle de choix pour les entreprises en quête d''un espace de travail premium.', 'Marrakech', 'Izdihar', 'KM7, N°17, Route de Safi, Izdihar, 40000 Marrakech', '40000', 'MA', NULL, NULL, 'immobilier', 'commercial_bureaux', 'commercial_bureaux', 'livre', 'en_commercialisation', 100, NULL, NULL, 'https://media.chridari.ma/98c18b6a-e1df-47f4-af08-7355820d8647/images/01KAEH9WA8W3SHGECPWG9HBCBD-medium.jpg', $j$["https://media.chridari.ma/98c18b6a-e1df-47f4-af08-7355820d8647/images/01KAEH9WA8W3SHGECPWG9HBCBD-medium.jpg", "https://media.chridari.ma/2636f640-43db-4568-bbc2-6f2f3452a229/images/01KAEH9RRWMMWYYJ0NB1HTCCQH-medium.jpg", "https://media.chridari.ma/a75eed8e-b9b5-4612-b5d9-15d3c1fb3f49/images/01KAEH9SZFY4BJYFR46BNGT7MJ-medium.jpg", "https://media.chridari.ma/49fbb6fe-082a-4701-990f-1dd0b8e0454d/images/01KAEH9V1BMG3W800CC4YZ27FP-medium.jpg"]$j$::jsonb, 'Plateau bureau', 'Climatisation ,  Sous-sol ,  Concierge ,  Ascenseur ,  Issue de secours ,  Parking ,  Terrasse ,  Vue sur la ville', 'Banque ,  Boulangerie ,  Café ,  Clinique ,  Salle de sport ,  Hammam ,  Bibliothèque ,  Maternelle ,  Centre commercial ,  École ,  Supermarché ,  Université', false, 863250.0, 863250.0, 897000.0, 'MAD', '52 – 74 m2', 'dc4a71f2-c4ed-596c-b255-785ef41de066', 'Tasnime immobilier', 'https://www.tasnime-immo.com/', $j$[{"id": "", "name": "RIDGENIE Génie civil - Bureau d'études des projets de construction", "role": "Partenaire / intervenant", "logo": "", "website": ""}, {"id": "", "name": "Bureau d'études techniques KMA CONSULT", "role": "Partenaire / intervenant", "logo": "", "website": ""}, {"id": "", "name": "Bureau d'études techniques METR ETUDE ET CONSEIL", "role": "Partenaire / intervenant", "logo": "", "website": ""}, {"id": "", "name": "C.T.R. (Construction Et Travaux Routiers)", "role": "Partenaire / intervenant", "logo": "", "website": ""}, {"id": "", "name": "MAITRE² ENTREPRISE GENERALE", "role": "Partenaire / intervenant", "l