INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT '033c4c28-ba72-5cc6-9784-13991c9f0bb0'::uuid, '71704bbb-5577-5b79-8bd6-b1e422382b95'::uuid, 'Al Boustane', 'Al Boustane - Studio, Duplex à Marrakech Al Boustane – Studios modernes et magasins à Marrakech Découvrez Al Boustane, un projet résidentiel contemporain situé dans le quartier de Rouidate, sur l''avenue Moulay Abdellah à Marrakech. Pensé pour offrir un cadre de vie confortable et fonctionnel, ce projet propose des studios modernes et des magasins avec mezzanine, alliant agencement optimisé, finitions soignées et équipements de qualité. Les logements disposent de cuisines entièrement équipées, de matériaux soigneusement sélectionnés et d''une isolation thermique et phonique conçue pour améliorer le confort au quotidien. Le projet bénéficie également d''équipements pratiques tels qu''un ascenseur, un parking privé, des balcons et une terrasse accessible. Grâce à sa localisation, Al Boustane offre un accès pratique aux commerces, écoles, établissements de santé, espaces verts et autres services de proximité. Que vous recherchiez un logement moderne à Marrakech ou une opportunité d''investissement immobilier, ce projet constitue une option à découvrir. Points forts : Studios modernes et magasins avec mezzanine Cuisines équipées et finitions de qualité Isolation thermique et phonique Parking privé, ascenseur et espaces extérieurs Emplacement pratique dans le quartier de Rouidate', 'Marrakech', 'Rouidate', 'Avenue Moulay Abdellah, Lot. Al Boustane, Lot N°C6, Rouidate, 40000 Marrakech', '40000', 'MA', NULL, NULL, 'immobilier', 'residentiel', 'residen