e-yk673", "chambres_min": "1", "chambres_max": "1", "seed_batch": "promoteurs_full_sifarah"}$j$::jsonb WHERE NOT EXISTS (SELECT 1 FROM public.projects x WHERE x.id = '033c4c28-ba72-5cc6-9784-13991c9f0bb0'::uuid OR x.attributes->>'source_project_id' = '033c4c28-ba72-5cc6-9784-13991c9f0bb0');
INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT '922117ed-c7b5-504e-af98-0ed1d69a726f'::uuid, 'ca1d780d-1697-5f07-b993-c5b3fde85b9d'::uuid, 'Villas Joury', '### Résidence haut de gamme au cœur de Marrakech Villas Joury est un projet résidentiel exclusif composé de 35 villas de luxe, niché dans un quartier en pleine croissance à Marrakech. Alliant modernité, sécurité et raffinement, cette résidence a été pensée pour répondre aux modes de vie les plus exigeants. ### Deux styles de villas pour deux façons de vivre - Villas en bande - Villas jumelées Toutes sont dotées d''une piscine privative et d''un jardin paysager, garantissant confort et intimité au quotidien. ### Des options sur mesure Villas Joury propose des configurations flexibles: - Finition au choix: finie ou semi-finie - Avec ou sans sous-sol - Personnalisation selon vos envies ### Une architecture élégante et fonctionnelle Pensée pour maximiser l''espace et la lumière, l''architecture mêle lignes modernes et matériaux de qualité, tout en s''intégrant harmonieusement dans un environnement résidentiel calme et sécurisé. ### Caractéristiques clés - Superficie allant de 250 à 490 m² - Surfaces habitables de 237 à 374 m² - Environnement sécurisé - Proximité des golfs, centres commerciaux, et grands axes', 'Marrakech', 'Chrifia', 'Route de Tahanaoute, Chrifia, 40000 Marrakech', '40000', 'MA', NULL, NULL, 'immobilier', 'residentiel', 'residentiel', 'en_construction', 'en_commercialisation', 55, '2026-12', NULL, 'https://media.chridari.ma/df5cb8c4-427a-494c-9d96-b71fbc2e67af/images/01JV7MAQ1K3P9JM23J6A9SR2DK-medium.jpg', $j$["https://media.chridari.ma/df5cb8c4-427a-494c-9d96-b71fbc2e67af/images/01JV7MAQ1K3P9JM23J6A9SR2DK-medium.jpg", "https://media.chridari.ma/e9f4b540-52c0-4dcd-8b71-2f2fc1643e6e/images/01JV7MAQFWHHR6R54YF2KK9WZZ-medium.jpg", "https://media.chridari.ma/ea27e2ee-ec46-4779-a3a9-f1e92898de11/images/01JV7MAQYT9DHA4KBH90XZTE3E-medium.jpg"]$j$::jsonb, 'Villa', 'Parking ,  Jacuzzi ,  Jardin privé ,  Sous-sol ,  Concierge ,  Cuisine équipée ,  Piscine ,  Terrasse ,  Système de sécurité', 'Centre commercial ,  Gare ,  Aéroport ,  Jardin public ,  Mosquée', false, 1800000.0, 1800000.0, 4200000.0, 'MAD', '250 – 490 m2', 'ca1d780d-1697-5f07-b993-c5b3fde85b9d', 'Villas Joury', 'https://villasjoury.com/', $j$[]$j$::jsonb, $j${"source_project_id": "922117ed-c7b5-504e-af98-0ed1d69a726f", "chridari_ref": "uovl8", "projet_id_legacy": "CHR-PRJ-uovl8", "reference_annonce": "MA241298", "entreprises_construction": "Karaouani Bâtiment (filiale 2JHL Holding)", "equipe_realisation_mentions": "Entreprise / réalisation: Karaouani Bâtiment — filiale 2JHL Holding (villasjoury.com/a-propos) | Entreprise (high): Karaouani Bâtiment — lien direct réalisation Villas Joury (reconfirmé user recheck)", "url_source": "https://chridari.ma/fr/projects/villas-joury-marrakech-uovl8", "chambres_min": "3", "chambres_max": "4", "seed_batch": "promoteurs_full_sifarah"}$j$::jsonb WHERE NOT EXISTS (SELECT 1 FROM public.projects x WHERE x.id = '922117ed-c7b5-504e-af98-0ed1d69a726f'::uuid OR x.attributes->>'source_project_id' = '922117ed-c7b5-504e-af98-0ed1d69a726f');
INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT 'fd948364-2ba1-56fb-8875-14fbf7ec3bb0'::uuid, 'ef835137-10d5-5516-b57d-3b153575bf00'::uuid, 'Zaraba Signature', 'Bienvenue à ZARABA SIGNATURE, une adresse exclusive sur la Route de l''Ourika à Marrakech, où le luxe prend forme à travers des villas d''exception sur des terrains de 1 000 m². Chaque Villa Oasis vous propose un style de vie raffiné et fonctionnel, avec: - Un vaste jardin paysager - Une piscine privée - Une grande terrasse pour profiter des moments en plein air L''intérieur allie confort et élégance: - 3 suites luxueuses, chacune avec dressing et salle de bain moderne avec douche à l''italienne - Double salon avec un coin cheminée chaleureux - Salle à manger lumineuse donnant directement sur la piscine - Cuisine américaine ouverte, moderne et conviviale - Salle de bain invités supplémentaire De larges baies vitrées favorisent une lumière naturelle abondante, créant un cadre de vie harmonieux et lumineux. L''emplacement, calme et sécurisé, vous garantit intimité et sérénité, à seulement 15 minutes du centre-ville de Marrakech. Une résidence idéale pour une vie paisible ou un investissement immobilier de standing.', 'Marrakech', 'Tassoultante', 'Route de l''Ourika, Lagouassem, Tassoultante, 40065 Marrakech', '40065', 'MA', NULL, NULL, 'immobilier', 'residentiel', 'residentiel', 'sur_plan', 'en_commercialisation', 15, '2026-06', NULL, 'https://media.chridari.ma/70c129f1-3fc1-4df1-bfcd-2a1ad9183ba9/images/01JTMYJ8W9HGXWXEPCPFBXNCZS-medium.jpg', $j$["https://media.chridari.ma/70c129f1-3fc1-4df1-bfcd-2a1ad9183ba9/images/01JTMYJ8W9HGXWXEPCPFBXNC